<script setup lang="ts">import { Head,Link,router } from '@inertiajs/vue3';import { Plus,Search } from '@lucide/vue';import { ref } from 'vue';import { Button } from '@/components/ui/button';import { Input } from '@/components/ui/input';type Customer={id:string;credit_limit:number;default_payment_term_days:number;is_active:boolean;person:{name:string;document_number:string|null;email:string|null;phone:string|null};default_price_list:{name:string}|null};const props=defineProps<{customers:{data:Customer[]};filters:{search:string};canManage:boolean}>();const search=ref(props.filters.search);const apply=()=>router.get('/customers',{search:search.value},{preserveState:true,replace:true});const money=(v:number)=>new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0}).format(v);</script>
<template><Head title="Clientes"/><main class="flex flex-1 flex-col gap-5 p-4 md:p-6"><header class="flex justify-between gap-3"><div><h1 class="text-2xl font-semibold">Clientes</h1><p class="text-sm text-muted-foreground">Condiciones comerciales y precios predeterminados.</p></div><Button v-if="canManage" as-child><Link href="/customers/create"><Plus/> Nuevo cliente</Link></Button></header><form class="flex max-w-xl gap-2" @submit.prevent="apply"><Input v-model="search" placeholder="Nombre o documento"/><Button type="submit" variant="outline"><Search/> Buscar</Button></form><section class="overflow-x-auto rounded-xl border bg-card"><table class="w-full text-sm"><thead class="border-b bg-muted/40 text-left"><tr><th class="px-4 py-3">Cliente</th><th class="px-4 py-3">Contacto</th><th class="px-4 py-3">Lista</th><th class="px-4 py-3">Crédito</th><th></th></tr></thead><tbody class="divide-y"><tr v-for="customer in customers.data" :key="customer.id"><td class="px-4 py-3"><Link :href="`/customers/${customer.id}`" class="font-medium text-amber-700 hover:underline">{{customer.person.name}}</Link><p class="text-xs text-muted-foreground">{{customer.person.document_number||'Sin documento'}}</p></td><td class="px-4 py-3">{{customer.person.phone||customer.person.email||'—'}}</td><td class="px-4 py-3">{{customer.default_price_list?.name||'Minorista'}}</td><td class="px-4 py-3">{{money(customer.credit_limit)}} · {{customer.default_payment_term_days}} días</td><td class="px-4 py-3 text-right"><Link v-if="canManage" :href="`/customers/${customer.id}/edit`" class="font-medium text-amber-700 hover:underline">Editar</Link></td></tr></tbody></table><p v-if="!customers.data.length" class="p-10 text-center text-sm text-muted-foreground">No hay clientes.</p></section></main></template>
